  if(cm==='week')return trSum()+`<div class="tkag">${days.map(d=>{const x=new Date(d+'T12:00');const L=on(d);return `<div class="tkag-d ${d===today()?'today':''}"><div class="tkag-h"><b>${wk[x.getDay()]} ${x.getMonth()+1}/${x.getDate()}</b>${d===today()?'<span class="pill p-needs">Today</span>':''}<span style="flex:1"></span><button type="button" class="btn small" data-pn="${d}">+ Reserve</button></div>
      ${L.length?L.map(r=>`<button type="button" class="tkag-r ${r.who===curUser?'me':''} ${RS.some(o=>overlaps(o,r))?'clash':''}" data-r="${r._id}"><span class="tkag-v">${vn(r.vid)}</span><span class="tkag-w">${esc(r.who||'')}${r.job?' · '+esc(r.job):''}</span><small>${r.allDay!==false?'All day':esc((r.t1||'')+'–'+(r.t2||''))}</small></button>`).join(''):'<div class="tkag-e">No reservations</div>'}</div>`}).join('')}</div>`;
